    Hypothesis PRE : ltac2:(zQ "10!snd@e$0?2fx?5HCEIL?1H?2sp?1A?3cap?4data?1p?2s0?2LB?4msF0?3mo0?5regs0?4mem0").

    Let cfg : Z := hdr_cfg data.
