    Let Hcalls : (1 <= calls <= 4)%nat. Proof. exact (hdr_calls_range data). Qed.
    Let FRM0 : FP.frm0 (@fp_csr fx). Proof. exact (atr_frm _ _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.

