    Section Loop.
      (* [comment removed for export] *)
      Variables (Dz OWz : Z) (cb : list block).
      Hypothesis COPY : ltac2:(zQ "f0!pf!hg6!o1!kt4!iq4!jd!lc!kta!ku0!hq4!hgc!is5!jkc!so7!in0@2$b@2$1@3$2$0?1NZ@2$1@3$2$0?2Dz$d@2$1@3$2$0?3OWzZ@3$2@1$6$5?2cb@1$7$5@2$1@2$e+1?1N@2$1@3$2$0?3OWz?2Dz@2$a$3\2pD$3@2$1@3$2@1$6$5?2cb@3$9@2$4@2$4$3$0$0@4$8@2$4$3$0$0@4$8$3$0^1?2Dz?1N@1$7@2$4@2$4$3$0$0@4$c?5HCEIL?1H?2Dz?1N").
      Let LB0 : list block := cb ++ LB.
      (* [comment removed for export] *)
      Variable K : ltac2:(zQ "10!sp6$0").
      Hypothesis HPOST : ltac2:(zQ "d0!sd!v1!v6!spe!ri2!std!tgc!hv0!th5!or8!ti0!rm2!rqe>3fx'$a>5regs'@2$6@1$0#5@1$1@1$0#k0>4mem'>0@1$1@1$0#k0@1$2@1$1@1$0#8>4msF'$3>3mo'$5>2s'@1$9?1H>0@h2$8?5HCEIL?1H^6?2sp?1A?3cap?4data?1p?2s0?2LB?3mo0?5regs0?4mem0^5^4^3^2^1@4$c$7$b@2$4^4^3?1K").

      (* [comment removed for export] *)
      Definition spent : ltac2:(zQ "20!hqb!pf>1k$0$1") := ltac2:(zQ "60!hqb!qs9!np2!io2!pjd!io9\1k$0@2$3@2$1?1H?1N@2$4@1$5^1@2$2?1H?1N").

      Let HD16 : Dz mod 16 = 0.
      Proof. destruct COPY as [(_ & -> & _) | (_ & _ & pD & _ & (_ & R2 & _))]; [reflexivity | exact R2]. Qed.

      (* [comment removed for export] *)
      Record lstate (k kc : nat) (r : Z) (regs : bvmap 5 word) (m : word -> option byte) (mo : Model) (sC : as_St H) (LBc : list block) : Prop := LS {
        ls_regs  : loop_base sp regs (Z_to_bv 64 N) (Z_to_bv 64 Dz) (Z_to_bv 64 OWz);
        ls_r     : getr regs 21 = Z_to_bv 64 r;
        ls_k4    : forall rr : reg, In rr ([24; 25; 26; 27]%bv : list reg) -> getr regs rr = getr regs0 rr;
        ls_tinv  : atinv m;
        ls_frame : tframe sp m (getr regs0 8) (getr regs0 9) (getr regs0 18) (getr regs0 19) (getr regs0 20) (getr regs0 21) (getr regs0 22) (getr regs0 23);
        ls_heap  : as_RHEAP H sC LBc m;
        ls_perm  : Permutation LBc LB0;
        ls_mpres : as_MPRES H mo0 mo;
        ls_copy  : rdn RSEGS m (Z_to_bv 64 Dz) (length ds) = Some ds;
        ls_cells : 1 <= N -> rw_cells asegs m Dz [CB (Z.to_nat N) ds];
        ls_caddr : 1 <= N -> addressable m Dz N;
        ls_sto   : sto k m;
        ls_ax    : axr m;
        ls_cb    : cb0 m;
        ls_bj    : bj_statics m;
        ls_al    : as_AL H sC >= as_AL H s0 - spent kc }.

      Let Hfd1 : forall mo, as_MPRES H mo0 mo -> fd_lookup (m_fds mo) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)).
      Proof. intros mo MP. destruct (adl_mpres H DL _ _ MP) as (_ & E & _). rewrite E. exact (atr_fd1 _ _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.
      Let Hfd2 : forall mo, as_MPRES H mo0 mo -> fd_lookup (m_fds mo) (Z_to_bv 64 2) = Some (FdChannel (Z_to_bv 64 2)).
      Proof. intros mo MP. destruct (adl_mpres H DL _ _ MP) as (_ & E & _). rewrite E. exact (atr_fd2 _ _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.
      Let Hfs : forall mo, as_MPRES H mo0 mo -> m_fs mo = m_fs mo0.
      Proof. intros mo MP. exact (proj1 (adl_mpres H DL _ _ MP)). Qed.

      Let TRC : adrv_traces H. Proof. exact (atr_tr _ _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.
      Let HCAP : Z.of_nat (length data) <= cap. Proof. exact (atr_cap _ _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.
      Let HAL0 : atr_cost H data <= as_AL H s0. Proof. exact (atr_al _ _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.
      Let COSTS : cost_laws H. Proof. exact (ah_costs H HH). Qed.

      (* [comment removed for export] *)
      Lemma tr_ret : forall (fxc : FPState) regs m msF mo sC LBf,
        as_VIS H sC msF = @mkst fxc regs (Z_to_bv 64 0xbec84) m rom -> as_AKREL H sC (mkCfg msF mo) -> FP.frm0 (@fp_csr fxc) ->
        loop_base sp regs (Z_to_bv 64 N) (Z_to_bv 64 Dz) (Z_to_bv 64 OWz) ->
        (forall rr : reg, In rr ([24; 25; 26; 27]%bv : list reg) -> getr regs rr = getr regs0 rr) ->
        atinv m -> tframe sp m (getr regs0 8) (getr regs0 9) (getr regs0 18) (getr regs0 19) (getr regs0 20) (getr regs0 21) (getr regs0 22) (getr regs0 23) ->
        as_RHEAP H sC LBf m -> Permutation LBf LB -> as_MPRES H mo0 mo -> sto calls m -> axr m -> cb0 m -> bj_statics m ->
        as_AL H sC >= as_AL H s0 - atr_cost H data ->
