      (* [comment removed for export] *)
      Lemma tr_call_harness : forall (fxc : FPState) k r regs m msF mo sC LBc (Kx : TSet),
        (k < calls)%nat ->
        as_VIS H sC msF = @mkst fxc regs (Z_to_bv 64 0xbec44) m rom -> as_AKREL H sC (mkCfg msF mo) -> FP.frm0 (@fp_csr fxc) ->
        lstate k k r regs m mo sC LBc ->
        (forall (fx' : FPState) regs' m' msF' mo' sC' LBc',
           as_VIS H sC' msF' = @mkst fx' regs' (Z_to_bv 64 0xbed14) m' rom -> as_AKREL H sC' (mkCfg msF' mo') -> FP.frm0 (@fp_csr fx') ->
           lstate k (S k) r regs' m' mo' sC' LBc' ->
           getr regs' 1 = Z_to_bv 64 0xbec68 -> getr regs' 11 = Z_to_bv 64 0 -> getr regs' 19 = Z_to_bv 64 0 ->
           realizes asegs (mkCfg msF' mo') Kx) ->
