      (* [comment removed for export] *)
      Lemma tr_printf_first : forall (fxc : FPState) r regs m msF mo sC LBc (Kx : TSet),
        as_VIS H sC msF = @mkst fxc regs (Z_to_bv 64 0xbed14) m rom -> as_AKREL H sC (mkCfg msF mo) ->
        lstate 0 1 r regs m mo sC LBc ->
        getr regs 1 = Z_to_bv 64 0xbec68 -> getr regs 11 = Z_to_bv 64 0 -> getr regs 19 = Z_to_bv 64 0 -> Kx [] ->
        (forall regs' m' msF' mo',
           as_VIS H sC msF' = @mkst fxc regs' (Z_to_bv 64 0xbec68) m' rom -> as_AKREL H sC (mkCfg msF' mo') ->
           lstate 1 1 r regs' m' mo' sC LBc -> getr regs' 19 = Z_to_bv 64 0 ->
           realizes asegs (mkCfg msF' mo') Kx) ->
        realizes asegs (mkCfg msF mo) (t_emit (W 1 [Z_to_bv 8 48; Z_to_bv 8 10]) Kx).
